from pathlib import Path
import json,csv
out=Path(__file__).parent
verified=json.loads((out/'SCHOLARQA_VERIFY.json').read_text());supp=json.loads((out/'SCHOLARQA_SUPPLEMENT_VERIFY.json').read_text())
rows=[]
def add(id,doi,title,claim,tier,url,loc,quote,summary,relationship,uncertainty):
 records=verified['items']+supp['items'];record=next(x['record'] for x in records if x['requested_id']==doi)
 rows.append(dict(id=id,paper_id=record['paperId'],stable_id=doi,title=title,authors=[x['name'] for x in record['authors']],year=record['year'],claim=claim,evidence_tier=tier,primary_url=url,locator=loc,short_exact_passage=quote,evidence_summary=summary,relationship=relationship,study_context='Electromagnetic inverse scattering' if id!='L05' else 'Nonlinear Bayesian inverse problems with Gaussian priors',confidence='High identity and stated method; limited for R7 equivalence',uncertainty=uncertainty))
add('L01','DOI:10.1016/j.wavemoti.2018.07.008','High-order functional derivatives of the scattered field according to the permittivity-contrast function','Arbitrary-order field derivatives and recursively induced source fields predate R7','A','https://arxiv.org/html/1803.00002v1','Sections2.3–2.4, equations14–27; HTML lines114–178; numerical limits lines240–243','functional derivative for any order','Repeated fictitious source currents generate higher-order fields; numerical Taylor convergence has a finite contrast range.','Supports prior-art boundary for raw jets, qualifies any unbounded convergence inference','arXiv title says diffracted, journal DOI/S2/publisher says scattered. Does not itself establish R7 compensated common-material order, equal-cost gain or certified working interval.')
add('L02','DOI:10.1109/TGRS.2009.2025122','Subspace-Based Optimization Method for Solving Inverse-Scattering Problems','SOM current/data decomposition is established; exact original text remains uninspected','C original identity; A later primary attribution','https://renchengsong.github.io/papers/TGRS2329032.pdf','Later Xu2015 author proof, printed pp2–3, equations3–7; PDF physical pp2–3, lines234–297; ref26 identifies Chen2010','the deterministic portion and the ambiguous part','Later primary paper attributes to Chen2010 an SVD split of the current-to-data GS map; retained current coefficients are recovered from measured data.','Supports current-space precursor, does not equate it with a material tangent spectrum','Original IEEE text inaccessible, S2 abstract publisher-elided. Later primary attribution is separate evidence, not direct original-paper TierA.')
add('L03','DOI:10.1088/0266-5611/25/8/085003','Twofold subspace-based optimization method for solving inverse scattering problems','TSOM second current subspace uses internal current-to-field structure','C original identity; A later primary attribution','https://renchengsong.github.io/papers/TGRS2329032.pdf','Later Xu2015, equations6–7 and accompanying text; HTML lines296–335, ref29 identifies Zhong2009','','Ambiguous currents are projected onto a restricted subspace formed from dominant GD singular vectors, separately from GS data visibility.','Supports pre-existing twofold physics/observation decomposition','Original IOP text restricted and abstract elided; exact original conventions and claims not verified in full text. No direct R7 compensation-order claim inferred.')
add('L04','DOI:10.1109/TAP.2017.2766658','Subspace-Based Distorted-Born Iterative Method for Solving Inverse Scattering Problems','S-DBIM combines nonlinear background updates with deterministic current retrieval','B','https://pure.bit.edu.cn/en/publications/subspace-based-distorted-born-iterative-method-for-solving-invers/','Original abstract reproduced in institutional record lines21–24; bibliography lines27–35','updates the Green\'s function for the inhomogeneous background at each step','The abstract reports improved field estimation and convergence from deterministic current retrieval with successive background Green updates.','Supports strong nonlinear/subspace baseline','Abstract-only evidence; no fresh replication of performance or detailed material constraints. Does not certify common-material finite-noise fibers.')
add('L05','ARXIV:1403.4680','Likelihood-informed dimension reduction for nonlinear inverse problems','Prior-relative generalized sensitivity and global posterior-averaged subspaces predate R7','A','https://arxiv.org/pdf/1403.4680','Section3.2, equations7–10, PDF pp6–7; lines281–408','Gauss-Newton approximation of the Hessian','Local spectra compare noise-weighted J-transpose-J against prior precision; global LIS averages the prior-preconditioned GN Hessian over posterior support.','Supports prior-art boundary for generic information spectra','Prior precision metric differs from R7 material-RMS pullback. This difference alone is not a novelty judgment; exact kernels, finite-distance compensation and gauge handling require separate proof.')
add('L06','DOI:10.1109/TGRS.2014.2329032','Multiplicative-Regularized FFT Twofold Subspace-Based Optimization Method for Inverse Scattering Problems','Multiple illumination currents are linked through one contrast material in a standard inverse-scattering formulation','A','https://renchengsong.github.io/papers/TGRS2329032.pdf','Author proof equations1–4; printed p2–3, physical PDF pp2–3, HTML lines176–253; contrast update across l at lines560–610','','One chi enters each incidence-specific constitutive current equation; multiple incidences jointly update that chi.','Supports shared-material multi-illumination as standard setup','Downloaded author PDF is a proof with duplicated proof/final blocks; cite printed equation numbers. Shared chi is not evidence for the exact R7 weighted compensation-conflict identity or its predictive utility.')
(out/'CLAIM_LEDGER.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
with (out/'CLAIM_LEDGER.tsv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]),delimiter='\t');w.writeheader();w.writerows(rows)
# Keep bounded passages and faithful summaries, not whole copyrighted web responses.
readback={'date':'2026-10-28','primary_evidence':[dict(id=r['id'],url=r['primary_url'],locator=r['locator'],evidence_tier=r['evidence_tier']) for r in rows],'access_failures':[{'url':'https://doi.org/10.1109/TGRS.2009.2025122','status':'web tool inaccessible'},{'url':'https://iopscience.iop.org/article/10.1088/0266-5611/25/8/085003','status':'restricted URL'},{'url':'https://www.sciencedirect.com/science/article/abs/pii/S0165212518301161','status':'403 on open; primary search result confirms journal title'},{'url':'https://intlpress.com/api/bgcloud-front/resource/pdf/volume/1806623525584740354-1806623525584740354-3747f05f8393d2ed6c7736b438747faa.pdf','status':'403; not used for substantive support'},{'url':'https://www.math.uci.edu/taxonomy/term/103?page=1','status':'502; author seminar search snippet contextual only'}],'publisher_title_confirmation':{'url':'https://www.sciencedirect.com/science/article/abs/pii/S0165212518301161','journal_title':'High-order functional derivatives of the scattered field according to the permittivity-contrast function','arxiv_variant':'diffracted field','resolution':'Same authors/year/DOI-ArXiv mapping verified by S2; do not silently label journal title as preprint title.'}}
(out/'WEB_PRIMARY_READBACK.json').write_text(json.dumps(readback,ensure_ascii=False,indent=2)+'\n')
collect=json.loads((out/'SCHOLARQA_COLLECT.json').read_text());(out/'RETRIEVAL_RECEIPT.json').write_text(json.dumps({'date':'2026-10-28','collect_queries':len(collect['search_queries']),'collect_operation_errors':len(collect['operation_errors']),'collect_candidates':len(collect['candidate_paper_ids']),'collect_process_status':'not separately captured by initial wrapper; inspect operation_errors, all6HTTP429','verify_process_status':json.loads((out/'VERIFY_PROCESS.json').read_text())['exit_status'],'verify_requested':verified['requested_count'],'verify_resolved':verified['resolved_count'],'verify_unresolved':verified['unresolved_ids'],'supplement_resolved':supp['resolved_count'],'no_exhaustive_novelty_claim':True,'new_Maxwell_RHS':0,'new_GT_read':False},indent=2)+'\n')
print('6 evidence rows saved; original5bibliographic identities verified; SOM/TSOM original passage gaps preserved')
